// Check if the polyhedron is valid
if (!poly.is_valid(false)) {
    poly.normalize_border();
    if (!poly.is_valid(false)) {
        return;
    }
}

// Collect all border halfedges
std::vector<typename Polyhedron::Halfedge_handle> border_edges;
for (typename Polyhedron::Halfedge_iterator he_it = poly.halfedges_begin();
     he_it != poly.halfedges_end(); ++he_it) {
    if (he_it->is_border()) {
        border_edges.push_back(he_it);
    }
}

// Group border edges into border cycles
std::vector<std::vector<typename Polyhedron::Halfedge_handle>> border_cycles;
std::vector<bool> visited(poly.size_of_halfedges(), false);
for (auto he : border_edges) {
    if (!visited[he->id()]) {
        std::vector<typename Polyhedron::Halfedge_handle> cycle;
        typename Polyhedron::Halfedge_handle current = he;
        do {
            visited[current->id()] = true;
            cycle.push_back(current);
            current = current->next();
        } while (current != he);
        border_cycles.push_back(cycle);
    }
}

// For each border cycle, create a new face to fill the hole
for (auto& cycle : border_cycles) {
    if (cycle.size() < 3) continue; // Skip degenerate holes

    // Create a new face
    typename Polyhedron::Face_handle new_face = poly.create_center_vertex(cycle.begin(), cycle.end());

    // Triangulate the new face (fan triangulation)
    typename Polyhedron::Halfedge_handle h = new_face->halfedge();
    typename Polyhedron::Halfedge_handle start = h;
    do {
        typename Polyhedron::Halfedge_handle next = h->next();
        if (next->next() != h) {
            poly.split_face(h, next);
        }
        h = next;
    } while (h != start);
}

// Ensure the polyhedron is valid after modifications
poly.normalize_border();
if (!poly.is_valid(false)) {
    poly.clear();
}
